def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    if N == 0:
        return 0

    grid = [[0] * N for _ in range(N)]
    for x, y, val in grid_values[:-1]:
        grid[x-1][y-1] = val

    def max_path_sum(x, y, visited, prev_x, prev_y):
        if x < 0 or y < 0 or x >= N or y >= N or (x, y) in visited:
            return -float('inf')
        if x == N - 1 and y == N - 1:
            return grid[x][y]

        visited.add((x, y))
        up = max_path_sum(x, y - 1, visited, prev_x, prev_y)
        down = max_path_sum(x, y + 1, visited, prev_x, prev_y)
        left = max_path_sum(x - 1, y, visited, prev_x, prev_y)
        right = max_path_sum(x + 1, y, visited, prev_x, prev_y)

        visited.remove((x, y))
        return max(up, down, left, right) + grid[x][y]

    return max(max_path_sum(0, 0, set(), -1, -1), max_path_sum(0, 0, set(), -1, -1))

