def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    values = [(x, y, value) for x, y, value in grid_values if value != 0]
    path_size = 2 * N - 2
    dp = [[0] * (path_size + 1) for _ in range(N)]

    def max_path_sum(i: int, j: int) -> int:
        if i == N - 1 and j == N - 1:
            return values[i][2]
        max_val = 0
        if i < N - 1:
            max_val = max(max_val, dp[i + 1][j])
        if j < N - 1:
            max_val = max(max_val, dp[i][j + 1])
        return max_val

    for way in range(path_size):
        for i in range(min(N-1, way) + 1):
            j = min(N-1, path_size-way) - i
            dp[i][j] = max_value_on_paths(N, values) + values[i][2] + values[j][2] - values[i+j][2] if values[i+j][2] != 0 else 0

    return dp[0][N-1]

