def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str or not 0 < N <= len(num_str) <= 100 or not 0 <= K <= N:
        raise ValueError("Invalid input")

    # Convert the number string to an array of digits
    digits = [int(digit) for digit in num_str]

    # Generate all possible partitions of the digits into K + 1 parts (the number, the multiplication signs, and the products)
    partitions = []
    for start in range(1, K + 1):
        for end in range(start, N):
            partitions.append(digits[start:end + 1])

    # Calculate all possible products from these partitions
    products = [1] * (K + 1)
    for start in range(1, K + 1):
        for end in range(start, N):
            products[start] += digits[end] * products[end - start + 1]

    # Find the maximum product
    max_product = max(products)

    return max_product

