            return "Invalid ISBN format. Expected '9' at the start."
        isbn = isbn.replace("-", "")
        if isbn.isdigit():
            total = 0
            for i in range(len(isbn)):
                total += int(isbn[i]) * ((13 - i) % 2 + 2)
            remainder = total % 10
            if remainder == 0:
                return "Right"
            else:
                return isbn.replace("-", "-" + str(10 - remainder))
        else:
            return "Invalid ISBN format. All digits should be valid."
    else:
        return "Invalid ISBN format. Expected either 10 or 13 digits."

def verify_isbn(isbn: str) -> str:
    # Regular expression to validate the ISBN format
    import re
    if not re.match(r'^\d{3}-\d{2}-\d{5}-\d{1}$|^X$', isbn):
        return 'Invalid format'

    # Remove the hyphen if it exists
    isbn = isbn.replace('-', '')

    # Calculate the checksum using the standard ISBN-13 algorithm
    def calculate_checksum(s):
        sum = 0
        for i, digit in enumerate(s):
            if i % 2 == 0:
                sum += int(digit) * 1
            else:
                sum += int(digit) * 3
        return sum % 10

    # Calculate the expected checksum
    expected_checksum = calculate_checksum(isbn[:-1])

    if expected_checksum != int(isbn[-1]):
        # If the actual checksum is incorrect, correct the ISBN by updating the last digit
        for digit in range(0, 10):
            corrected_isbn = isbn[:-1] + str(digit)
            if calculate_checksum(corrected_isbn[:-1]) == int(corrected_isbn[-1]):
                return corrected_isbn

    return 'Right'

def verify_isbn(isbn: str) -> str:
    if not isinstance(isbn, str) or len(isbn) != 13 or not isbn.replace('-', '').isdigit():
        return "Invalid format, please provide a valid ISBN number."

    def isbn_checksum校验(isbn: str):
        number = int(isbn.replace('-', '').replace('X', '10'))
        checksum = 0
        for i in range(13):
            digit = int(isbn[i])
            if i % 2 == 0:
                checksum += digit
            else:
                checksum += digit * 3
        checksum %= 11
        if checksum == 0:
            return '0'
        return str(11 - checksum).upper()

    correct_checksum = isbn_checksum(isbn)
    if correct_checksum == isbn[-1]:
        return "Right"
    else:
        return isbn

