    pair_counts = [[0] * (N+1) for _ in range(M+1)]
    for i in range(M):
        for j in range(N):
            for (Xl, Yl, Xr, Yr) in chatting_pairs:
                if Xl <= i <= Xr and Yl <= j <= Yr:
                    pair_counts[i+1][j+1] += 1

