    row_chats = [[0 for _ in range(cols)] for _ in range(rows)]
    col_chats = [[0 for _ in range(cols)] for _ in range(rows)]

    # Count chatting pairs for each row and column
    for x, y, pi, qi in chatting_pairs:
        row_chats[x][y] += 1
        row_chats[pi][qi] += 1
        col_chats[x][y] += 1
        col_chats[pi][qi] += 1

    # Calculate row and column collaboration scores
    row_scores = [0 for _ in range(rows)]
    col_scores = [0 for _ in range(cols)]

    for i in range(rows):
        for j in range(cols):
            if row_chats[i][j] > 0:
                row_scores[i] = max(row_scores[i], sum(row_chats[i]))

    for j in range(cols):
        for i in range(rows):
            if col_chats[i][j] > 0:
                col_scores[j] = max(col_scores[j], sum(col_chats[i]))

    # Select the optimal row and column indices for aisles
    optimal_rows = []
    optimal_cols = []

    for i in range(rows):
        for j in range(cols):
            if row_scores[i] + col_scores[j] >= D:
                optimal_rows.append(i)
                optimal_cols.append(j)

    if len(optimal_rows) <= K:
        optimal_rows = [row for row in optimal_rows if len(set([tuple(pair) for pair in [chatting_pairs[i-j-1] for i in optimal_rows])]) == 1]
        optimal_rows.sort()

    if len(optimal_cols) <= L:
        optimal_cols = [col for col in optimal_cols if len(set([tuple(pair) for pair in [chatting_pairs[j-i-1] for j in optimal_cols])]) == 1]
        optimal_cols.sort()

    # Combine the optimal row and column indices
    row_str = ' '.join(map(str, optimal_rows))
