def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    if not all(isinstance(i, tuple) and len(i) == 4 for i in chatting_pairs):
        raise ValueError("chatting_pairs should be a list of tuples, each containing 4 integers")

    aisle_positions = set()
    aisle_cost = {pos: 0 for pos in chatting_pairs}

    def calculate_cost(subset):
        cost = 0
        for pair in subset:
            cost += 1
        return cost

    def dfs(n: int, used_columns: set, used_rows: set):
        nonlocal aisle_positions
        nonlocal aisle_cost
        if n >= K + L:
            dp_row, dp_col = used_columns.copy(), used_rows.copy()
            dp_row.discard(0)
            dp_col.discard(0)
            i, j = 1, 1
            while i - 1 in dp_row and i <= M:
                while j - 1 in dp_col and j <= N:
                    if (i, j) in aisle_cost:
                        while (i, j) in aisle_positions:
                            aisle_positions.remove((i, j))
                            aisle_cost.pop((i, j))
                    else:
                        aisle_positions.add((i, j))
                        aisle_cost[(i, j)] = calculate_cost([(x, y) for x, y in chatting_pairs if x <= i <= y and y <= j <= x])
                    i += 1
                j += 1
            best_row, best_col = dp_row.pop(), dp_col.pop()
            last_row, last_col = best_row - 1, best_col - 1
            # Add missing aisles to maximize chat
            if last_row > 0: missile = M - (last_row - best_row - 1)
            else: missile = 0
            if last_col > 0: aviation = N - (last_col - best_col - 1)
            else: aviation = 0
            if missile != 0: aisle_positions.add((last_row, best_col))
            if aviation != 0: aisle_positions.add((best_row, last_col))
            return best_row, best_col

        for i in range(1, M + 1):
            for j in range(1, N + 1):
                if i not in used_columns and j not in used_rows:
                    used_columns.add(i)
                    used_rows.add(j)
                    res = dfs(n + 1, used_columns, used_rows)
                    if res:
                        if calculate_cost([(x, y) for x, y in chatting_pairs if x <= i <= y and y <= j <= x]) < aisle_cost[res]:
                            aisle_cost[res] = calculate_cost([(x, y) for x, y in chatting_pairs if x <= i <= y and y <= j <= x])
                            aisle_positions = res.copy()
                    used_columns.discard(i)
                    used_rows.discard(j)

    dfs(0, set(), set())
    row_index = aisle_positions.pop()
    col_indices = [can.position for can in aisle_positions]
    return str(row_index), ' '.join(map(str, col_indices))

