def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        return 0

    # Initialize DP table with zeros
    dp = [[0 for _ in range(m+1)] for _ in range(n)]

    # Base case: only one way to be at the starting point after 0 passes
    for i in range(n):
        dp[i][0] = 1

    # Fill DP table based on transitions
    for i in range(1, n):
        for j in range(1, m+1):
            dp[i][j] = (dp[(i-1) % n][j-1] + dp[(i+1) % n][j-1]) % 1000000

    return dp[0][m]

import math

def count_passing_ways(n: int, m: int) -> int:
    if n <= 1 or m < 1 or m > 2 * n:
        return 0  # Invalid input handling

    # Define a dynamic programming table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: When ball returns to starting student
    dp[1][0] = 1

    # Fill the DP table
    for i in range(2, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = (i * dp[i - 1][j] + dp[i - 1][j - 1]) % (math.factorial(i - 1) // math.factorial(m - j))

    return dp[n][m]

