def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 2D array to store maximum importance values for given budget
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Iterate over each item and budget
    for i in range(m+1):
        for j in range(n+1):
            # If the item can be added to the knapsack, choose the maximum importance value
            if items[i-1][0] <= j:
                dp[i][j] = max(items[i-1][1] + dp[i-1][j-items[i-1][0]], dp[i-1][j])
            else:
                # Otherwise, take the max value from the previous item
                dp[i][j] = dp[i-1][j]

    # The maximum importance value that can be achieved with the given budget
    return dp[m][n]

def max_energy(beads):
    """
    Calculate the maximum energy that can be released by merging beads on a necklace.

    Args:
        beads: A list of integers where each integer represents the head value of a bead and
               the tail value of the previous bead. The tail value of the last bead is assumed
               to match the head value of the first bead due to the circular nature of the necklace.

    Returns:
        An integer representing the maximum energy that can be obtained by optimally merging all beads.

    Examples:
        >>> max_energy([2, 3, 5, 10])
        710
        >>> max_energy([1, 2, 3, 4])
        48
    """
    def dp(i, j):
        if i == j:
            return beads[i]
        if dp(i + 1, j) > dp(i, j - 1) and beads[i] == beads[j - 1]:
            return dp(i + 1, j) * beads[i]
        else:
            return dp(i, j - 1)

    return max(dp(i, n) + dp(i + 1, j) * beads[i] for i in range(n) for j in range(i + 1, n) if beads[i] == beads[j])

def max_energy(beads):
    n = len(beads)
    dp = [[0] * n for _ in range(n)]

    for length in range(1, n + 1):
        for left in range(n - length + 1):
            right = left + length - 1
            if left < right:
                dp[left][right] = dp[left + 1][right] + beads[left - 1] * beads[right]
                for mid in range(left + 1, right):
                    dp[left][right] = max(dp[left][right], dp[left][mid] * beads[mid + 1] * beads[right])

    return dp[0][n - 1]

def max_energy(beads):
    energy_points = [0] * len(beads)

    # Iterate through each bead and calculate energy points for merging
    for i in range(len(beads)):
        if i > 0:
            energy_points[i] = max(energy_points[i], energy_points[i - 1])

        for j in range(i + 1, len(beads)):
            if beads[i] == beads[j]:
                energy_points[j] = max(energy_points[j], energy_points[i] * beads[i] * beads[j])

    return max(energy_points)

