def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or n - k * x + 1 < k:
        return 0

    def count_partitions_helper(start, remain, parts):
        if parts == k:
            return remain == 0
        if start > n or remain < 0:
            return 0
        n_ways = 0
        for i in range(start, n // x + 1):
            n_ways += count_partitions_helper(i + 1, remain - x * i, parts + 1)
        return n_ways

    return count_partitions_helper(1, n, 1)

