def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x or x == 0:
        return 0

    result = math.comb(n + k - 1, k - 1)

    # Handle cases where the smallest part is greater than x
    for i in range(x, k * x + 1):
        if n < i * k:
            result -= math.comb(i * k - 1, k - 1)
            break

    return result

def count_partitions(n: int, k: int, x: int) -> int:
    # Validate input parameters
    if not isinstance(n, int) or not isinstance(k, int) or not isinstance(x, int):
        raise ValueError("All parameters must be integers")
    if k <= 0:
        raise ValueError("Number of parts k must be positive")
    if n < k * x:
        raise ValueError("The sum of parts (k*x) must be less than or equal to n")

    # Initialize dynamic programming table
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # Base case:Partitioning 0 into 0 parts is always possible
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            dp[i][j] = dp[i - 1][j]
            if i >= x * j:
