def preorder_traversal(inorder: str, postorder: str) ->str:
    if not inorder or not postorder or len(inorder) != len(postorder):
        raise ValueError("Invalid input values")

    def build_tree(inorder, postor):
        if not inorder:
            return None

        root = postor[-1]
        root_index = inorder.index(root)

        left_inorder = inorder[:root_index]
        right_inorder = inorder[root_index+1:]
        left_postor = postor[:root_index]
        right_postor = postor[root_index:-1]

        return TreeNode(root, build_tree(left_inorder, left_postor), build_tree(right_inorder, right_postor))

    def build_tree_core(inorder, inorder_index_map, inorder_end, postor, postor_idx_map, postor_end, result):
        if postor_idx_map[postor[postor_idx]]:
            result.append(postor[postor_idx])
            postor_idx_map[postor[postor_idx]] = -1

        if postor_idx_map[postor[postor_idx - 1]]:
            return

        next_index = postor_idx_map[postor[postor_idx - 1]]

        if next_index != -1:
            build_tree_core(inorder, inorder_index_map, postor_idx_map[postor[next_index - 1]] - 1, postor, postor_idx_map, next_index, result)
            result.append(postor[postor_idx - 1])
            postor_idx_map[postor[next_index - 1]] = -1

        if postor_idx <= postor_end:
            build_tree_core(inorder, inorder_index_map, postor_idx_map[postor[postor_idx]], postor, postor_idx_map, postor_end, result)

    inorder_index_map = {k: i for i, k in enumerate(inorder)}
    postor_idx_map = {k: i for i, k in enumerate(postorder)}

    result = []

    build_tree_core(inorder, inorder_index_map, 0, postorder, postor_idx_map, len(postorder) - 1, result)

    return ''.join(result)

