    # Helper function to calculate the score of a single game
    def game_score(score_str):
        player_score, opponent_score = 0, 0
        for c in score_str:
            player_score += 1 if c == 'W' else -1
            if player_score < 0 or player_score > system:
                player_score = 0
            opponent_score += 1 if c == 'L' else -1
            if opponent_score < 0 or opponent_score > system:
                opponent_score = 0
            score = f"{player_score}:{opponent_score}"
            yield score

    # Process the string into game scores for each part
    game_scores = []
    for part in points.split('L'):
        score_str = part + 'L' if part and part[-1] != 'L' else ''
        score = list(game_score(score_str))
        game_scores.extend(score)

    return game_scores

