def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # Initialize a DP table with dimensions (T+1) x (M+1)
    dp = [[0 for _ in range(M+1)] for _ in range(T+1)]

    for i in range(1, T+1):
        for j in range(1, M+1):
            # If the herb times are within the allowed range
            if herbs[j-1][0] <= i:
                # Take the maximum value between not picking the herb and picking it
                dp[i][j] = max(dp[i][j-1], dp[i-herbs[j-1][0]][j-1] + herbs[j-1][1])
            else:
                # If the herb times exceed the allowed range, skip it
                dp[i][j] = dp[i][j-1]

    # The maximum value can be found in the last row of the DP table
    return dp[T][M]

