def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # If the box is already full, no items can be packed
    if V <= 0:
        return 0

    # Initialize the DP array where dp[row][col] represents the maximum volume that can be occupied with row items
    dp = [[0 for _ in range(V + 1)] for _ in range(n + 1)]

    # Build the DP table
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    # The minimum remaining space is the difference between the box's capacity and the maximum occupied volume
    return V - dp[n][V]

