    def comb(n, k):
        if k > n:
            return 0
        elif k == 0 or k == n:
            return 1
        else:
            return comb(n-1, k-1) + comb(n-1, k)

    # Sort the types to ensure increasing arrangement
    types = sorted(zip(a, range(n)))

    count = 0
    for i in range(n):
        for j in range(m):  # Fill up to m pots
            if j + types[i][0] > m or j == m and types[i][0] > m % (j + types[i][0]):
                break
            count = (count + comb(m - j - 1, m - i - 1)) % MOD

    return count

