def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must consist only of alphabetic characters")

    def shift(ch: str, shift_num: int) -> str:
        if ch.isupper():
            offset = ord('A')
        else:
            offset = ord('a')
        return chr((ord(ch) - offset + shift_num) % 26 + offset)

    key_index = 0
    decrypted = []
    for char in ciphertext:
        letter = key[key_index]
        shift_num = ord(letter) - ord('a')
        decrypted.append(shift(char, -shift_num))
        key_index = (key_index + 1) % len(key)

    return ''.join(decrypted)

