def mod_inverse(a, b):
    if b == 0:
        return None
    x, y, gcd = 0, 1, b
    while a:
        q = gcd // a
        gcd = gcd % a
        x, y = y - q * x, x
    if gcd == 1:
        if y < 0:
            y += b
        return y
    else:
        return None

