def min_groups(w, n, prices):
    if not w or not n:
        return 0

    total_price = sum(prices)
    if total_price > w:
        return -1  # No valid groups can be formed

    if n <= 2:
        return n  # Only one group needed

    counts = [0] * (total_price + 1)
    counts[0] = 1  # Any number can be formed with 0 items

    for i in range(1, len(counts)):
        for j in range(n):
            if i - prices[j] >= 0:
                counts[i] += counts[i - prices[j]]

    # Find the minimum number of groups required
    min_groups_required = float('inf')
    for i in range(1, total_price + 1):
        if counts[i] == n:
            min_groups_required = min(min_groups_required, counts[i])
            break

    return min_groups_required

def min_groups(w, n, prices):
    def valid_group(group_price):
        return group_price <= w

    groups = []
    for i in range(0, n, 2):
        group = [prices[i], prices[i + 1]] if i + 1 < n else [prices[i]]
        if valid_group(sum(group)):
            groups.append(group)

    return len(groups)

def hanoi_double_iterative(n: int) -> int:
