def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("Number of discs must be at least 1")

    # The recurrence relation for the number of moves in the double-disc Hanoi Towers
    total_moves = 2 * (2 ** n - 1)

    return total_moves

def hanoi_double_iterative(n: int) -> int:
    # Base cases
    if n == 1:
        return 2
    elif n == 2:
        return 6
    elif n == 3:
        return 14

    # Recursive step: calculate minimum moves for n-1 pairs a la斐波那契 sequence
    moves_n_minus_1 = 2 * hanoi_double_iterative(n - 1)

    # Each move for n pairs adds 2 more moves for transferring the pair across twice (to B to check and return to C or vice versa)
    return moves_n_minus_1 + 2 * (n - 1)

def hanoi_double_iterative(n: int) -> int:
    # Base cases
    if n == 1:
        return 2
    elif n == 2:
        return 6

    # Recursive relation for double-disc Hanoi Towers
    moves = 2 * hanoi_double_iterative(n - 1) + 2 * n - 2
    return moves

