    if n <= 0 or k <= 0:
        raise ValueError("Initial number of cigarettes and number of butts must be positive.")

    total_cigarettes = n
    remaining_butts = n

    while remaining_butts >= k:
        total_cigarettes += 1
        remaining_butts -= k

    return total_cigarettes

def total_smoked_cigarettes(n, k):
    if not isinstance(n, int) or not isinstance(k, int):
        raise ValueError("Both n and k must be integers")
    if n < 0 or k < 0:
        raise ValueError("Both n and k must be non-negative")
    num_cigarettes = n

    while num_cigarettes >= k:
        num_cigarettes = num_cigarettes - k + 1

    return num_cigarettes

def total_smoked_cigarettes(n, k):
    if n < k:
        return n  # Not enough butts to exchange
    total = n
    while n >= k:
        total += n // k  # Add new cigarettes
        n = (n + k - 1) // k  # Calculate new cigarettes after exchange
    return total
